fn absx(x: Vec<i32>) -> Vec<i32> {
    // Pre-allocate output vector with the same length as the input
    let mut y = Vec::with_capacity(x.len());
    
    for v in x {
        // We assume v != i32::MIN, so negating v when v < 0 cannot overflow.
        let abs_v = if v >= 0 { v } else { -v };
        y.push(abs_v);
    }
    
    y
}

